      : `<path d='M282 476C272 362 332 314 402 314S528 362 518 476C500 424 462 398 400 398S300 424 282 476Z' fill='${look.hair}'/>`;
  const art = [
    `<rect width='800' height='1000' fill='${look.wall}'/>`,
