          setLog((lines) => [...lines, `Attempt ${attempt}: ${attemptId.slice(0, 8)}`]);
          await wait(900);
          step.authenticating();
          await wait(1500);
          if (attempt === 1) throw new Error("Your bank declined the card. Nothing was charged.");
