  const next = useRef(0);
  return {
    items,
    onToggle: (id: string, done: boolean) => setItems((list) => list.map((item) => (item.id === id ? { ...item, done } : item))),
    onAdd: (label: string) => {
      next.current += 1;
      setItems((list) => [...list, { id: `new-${next.current}`, label }]);
    },
    onRemove: (id: string) => setItems((list) => list.filter((item) => item.id !== id)),
