    for (let col = 0; col < ROADS_X.length - 1; col += 1) {
      const x = (ROADS_X[col] ?? 0) + 14;
      const y = (ROADS_Y[row] ?? 0) + 14;
      cells.push({ x, y, w: (ROADS_X[col + 1] ?? 0) - x - 14, h: (ROADS_Y[row + 1] ?? 0) - y - 14, park: col === 1 && row === 2, col, row });
