/** 45 -> "45 min", 75 -> "1 h 15 min", 120 -> "2 h". */
function minutes(value: number): string {
  if (value < 60) return `${value} min`;
  const hours = Math.floor(value / 60);
  const rest = value % 60;
  return rest ? `${hours} h ${rest} min` : `${hours} h`;
}

