function photo(kind: "dunes" | "arches" | "ridge" | "sea", palette: keyof typeof PALETTES, seed: number, w = 1200, h = 800): string {
  const p = PALETTES[palette];
  const c = (i: number) => p[Math.min(5, i)] ?? "#888";
